func TestParseRulesSupportsJSONAndFlatConfiguration(t *testing.T) {
	t.Parallel()

	rules, err := ParseRules(`[{"files":"README.md","from":["old","older"],"to":"new","literal":true}]`, FlatConfig{})
	require.NoError(t, err)
	require.Len(t, rules, 1)
	require.Equal(t, StringList{"README.md"}, rules[0].Files)
	require.Equal(t, StringList{"old", "older"}, rules[0].From)
	require.True(t, rules[0].Literal)

	rules, err = ParseRules("", FlatConfig{
		Files:  "README.md, docs/**/*.md",
		Ignore: "docs/archive/**",
		From:   `v\d+`,
		To:     "v2",
	})
	require.NoError(t, err)
	require.Equal(t, StringList{"README.md", "docs/**/*.md"}, rules[0].Files)
	require.Equal(t, StringList{"docs/archive/**"}, rules[0].Ignore)
}

func TestApplySupportsGlobsRegexTemplatesAndIgnore(t *testing.T) {
	t.Parallel()
	root := t.TempDir()
	writeFixture(t, root, "README.md", "badge-version-1.2.3\n", 0o640)
	writeFixture(t, root, "docs/guide.md", "version-1.2.3\n", 0o644)
	writeFixture(t, root, "docs/archive/old.md", "version-1.2.3\n", 0o644)

	changed := true
	one := 1
	result, err := Apply(Config{
		Root: root,
		Rules: []Replacement{{
			Files:   StringList{"README.md", "docs/**/*.md"},
			Ignore:  StringList{"docs/archive/**"},
			From:    StringList{`(?m)version-\d+\.\d+\.\d+`},
			To:      "version-${nextRelease.version}",
			Results: []ResultAssertion{{File: "README.md", HasChanged: &changed, NumMatches: &one, NumReplacements: &one}},
		}},
		Template: TemplateData{NextVersion: "2.0.0"},
	})
	require.NoError(t, err)
	require.Equal(t, []string{"README.md", "docs/guide.md"}, result.ModifiedFiles())
	requireFileContains(t, filepath.Join(root, "README.md"), "badge-version-2.0.0")
	requireFileContains(t, filepath.Join(root, "docs", "guide.md"), "version-2.0.0")
	requireFileContains(t, filepath.Join(root, "docs", "archive", "old.md"), "version-1.2.3")
	info, err := os.Stat(filepath.Join(root, "README.md"))
	require.NoError(t, err)
	require.Equal(t, os.FileMode(0o640), info.Mode().Perm())
}

func TestApplyEvaluatesAllAssertionsBeforeWriting(t *testing.T) {
	t.Parallel()
	root := t.TempDir()
	writeFixture(t, root, "one.txt", "old", 0o644)
	writeFixture(t, root, "two.txt", "old", 0o644)
	wantTwo := 2

	_, err := Apply(Config{
		Root: root,
		Rules: []Replacement{{
			Files:   StringList{"*.txt"},
			From:    StringList{"old"},
			To:      "new",
			Results: []ResultAssertion{{File: "two.txt", NumMatches: &wantTwo}},
		}},
	})
	require.EqualError(t, err, "replacement 1: two.txt: numMatches = 1, want 2")
	requireFileContains(t, filepath.Join(root, "one.txt"), "old")
	requireFileContains(t, filepath.Join(root, "two.txt"), "old")
}

func TestApplyDryRunPreservesCRLFAndFiles(t *testing.T) {
	t.Parallel()
	root := t.TempDir()
	writeFixture(t, root, "version.txt", "version=1\r\nnext=1\r\n", 0o644)

	result, err := Apply(Config{
		Root:   root,
		DryRun: true,
		Rules: []Replacement{{
			Files: StringList{"version.txt"},
			From:  StringList{`(?s)version=.*`},
			To:    "version=2\nnext=2\n",
		}},
	})
	require.NoError(t, err)
	require.Equal(t, []string{"version.txt"}, result.ModifiedFiles())
	content, err := os.ReadFile(filepath.Join(root, "version.txt"))
	require.NoError(t, err)
	require.Equal(t, "version=1\r\nnext=1\r\n", string(content))
}

func TestApplyRejectsEscapingPattern(t *testing.T) {
	t.Parallel()
	_, err := Apply(Config{
		Root: t.TempDir(),
		Rules: []Replacement{{
			Files: StringList{"../outside"},
			From:  StringList{"old"},
			To:    "new",
		}},
	})
	require.EqualError(t, err, `replacement 1: file pattern "../outside" must stay within the working directory`)
}

